import{_ as a,a0 as l,w as r,s as p,I as i,x as t,a1 as d,A as o,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"findmnt-寻找挂载的文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"findmnt-寻找挂载的文件系统 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"findmnt-寻找挂载的文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"findmnt-寻找挂载的文件系统 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Linux findmnt Command To Find Mounted Filesystems","title":"findmnt-寻找挂载的文件系统","tag":"201405","desc":""},"relativePath":"201405/Linux findmnt Command To Find Mounted Filesystems.md","filePath":"[post].md"}'),s={name:"201405/Linux findmnt Command To Find Mounted Filesystems.md"};function f(u,n,h,x,g,c){const e=l("Link");return r(),p("div",null,[n[14]||(n[14]=i("h1",{id:"findmnt-寻找挂载的文件系统",tabindex:"-1"},[t("findmnt-寻找挂载的文件系统 "),i("a",{class:"header-anchor",href:"#findmnt-寻找挂载的文件系统","aria-label":"Permalink to “findmnt-寻找挂载的文件系统”"},"​")],-1)),n[15]||(n[15]=i("p",null,"命令findmnt用来查找在Linux下已经被挂载的文件系统。该命令会从/etc/fstab、/etc/mtab或者/proc/self/mountinfo中寻找指定的文件系统。",-1)),n[16]||(n[16]=i("h3",{id:"如何安装findmnt",tabindex:"-1"},[t("如何安装findmnt "),i("a",{class:"header-anchor",href:"#如何安装findmnt","aria-label":"Permalink to “如何安装findmnt”"},"​")],-1)),i("p",null,[n[1]||(n[1]=t("findmnt命令来自于util-linux-ng软件包，这个包现在改名为util-linux。该软件包中还包括其他一些工具，比如hwclock等。从kernel.org ftp页面",-1)),d(e,{href:"ftp://ftp.kernel.org/pub/linux/utils/util-linux/"},{default:o(()=>[...n[0]||(n[0]=[t("下载util-linux",-1)])]),_:1}),n[2]||(n[2]=t("以安装findmnt。",-1))]),n[17]||(n[17]=m(`<h3 id="如何在fedora下安装findmnt" tabindex="-1">如何在Fedora下安装findmnt <a class="header-anchor" href="#如何在fedora下安装findmnt" aria-label="Permalink to “如何在Fedora下安装findmnt”">​</a></h3><p>Fedora用户可以通过下面的命令安装该软件包：</p><pre><code>$ sudo yum install util-linux-ng
</code></pre><h3 id="findmnt默认选项" tabindex="-1">Findmnt默认选项 <a class="header-anchor" href="#findmnt默认选项" aria-label="Permalink to “Findmnt默认选项”">​</a></h3><p>如果没有提供特定的挂载点或者设备，该命令默认会以优美的树形结构列出所有已经被挂载的文件系统。</p><pre><code>$ findmnt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-default.png" alt="findmnt default"></p><h3 id="findmnt轮询模式" tabindex="-1">Findmnt轮询模式 <a class="header-anchor" href="#findmnt轮询模式" aria-label="Permalink to “Findmnt轮询模式”">​</a></h3><p>findmnt可以被用来监控/proc/self/mountinfo文件的变化。轮询模式可以通过下面的命令进行调用：</p><pre><code>$ findmnt -p
</code></pre><p>或者</p><pre><code>$ findmnt --poll
</code></pre><p>/proc/self/mountinfo文件的任何变化会自动的在终端中进行更新。一开始你不会发现终端中的输出有任何变化，如果此时你拔掉U盘再插入，变化就会出现在终端中。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-poll.png" alt="findmnt poll"></p><p>轮询停止的时间可以通过<strong>--timeout</strong>或者<strong>--first-only</strong>选项进行限制。</p><h3 id="超时选项" tabindex="-1">超时选项 <a class="header-anchor" href="#超时选项" aria-label="Permalink to “超时选项”">​</a></h3><p>该选项可以与--pool一起使用来限制轮询模式的时间。<strong>超时单位是毫秒</strong>。超过此时间后，findmnt不会再监控/proc/self/mountinfo文件的变化。</p><pre><code>$ findmnt --poll --timeout 6000
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-poll-timeout.png" alt="findmnt poll timeout"></p><h3 id="first-only选项" tabindex="-1">First-only选项 <a class="header-anchor" href="#first-only选项" aria-label="Permalink to “First-only选项”">​</a></h3><p>first-only选项只会监控/proc/self/mountinfo文件的第一次变化，之后该命令退出轮询模式。第一次变化会出现在终端中，并且返回到提示符。使用此选项在终端中输入：</p><pre><code>$ findmnt --poll --first-only
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-poll-first-only.png" alt="findmnt poll first-only"></p><h3 id="模仿df输出的选项" tabindex="-1">模仿df输出的选项 <a class="header-anchor" href="#模仿df输出的选项" aria-label="Permalink to “模仿df输出的选项”">​</a></h3><p>findmnt命令也可以用来模仿df命令的输出。你可以参考如下的命令使用findmnt和选项<strong>--df</strong>。</p><pre><code>$ findmnt --df
</code></pre><p>或者</p><pre><code>$ findmnt -D
</code></pre><p>它会返回和<strong>df -h</strong>命令几乎相同的输出。</p><pre><code>$ df -h
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-imitate-df.png" alt="findmnt imitate df"></p><h3 id="findmnt-list选项" tabindex="-1">Findmnt list选项 <a class="header-anchor" href="#findmnt-list选项" aria-label="Permalink to “Findmnt list选项”">​</a></h3><p>如果你不喜欢默认的树形输出，你可以使用<strong>--list</strong>或者<strong>-l</strong>选项。它会以列的形式进行输出。</p><pre><code>$ findmnt --list
</code></pre><p>执行此命令的输出如下：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-list.png" alt="findmnt list"></p><h3 id="findmnt-evaluate-选项" tabindex="-1">Findmnt Evaluate 选项 <a class="header-anchor" href="#findmnt-evaluate-选项" aria-label="Permalink to “Findmnt Evaluate 选项”">​</a></h3><p>求值选项会转换所有的标签(比如LABEL，UUID，PARTUUID或者PARTLABEL)成真实的设备名称。该选项可以结合<strong>--fstab</strong>选项来打印所有在/etc/fstab中包含的文件系统。<strong>--fstab</strong>选项的输出是列的形式，因此当使用<strong>--fstab</strong>的时候无需使用<strong>--list</strong>选项。</p><pre><code>$ findmnt --fstab --evaluate
</code></pre><p>当这两个选项像如下一样结合使用的时候，输出如下：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-fstab-evaluate.png" alt="findmnt fstab evaluate"></p><h3 id="findmnt-type-选项" tabindex="-1">Findmnt type 选项 <a class="header-anchor" href="#findmnt-type-选项" aria-label="Permalink to “Findmnt type 选项”">​</a></h3><p>该选项允许你限制打印出的文件系统。多个文件系统可以使用逗号分割进行指定。在这个实例中，该命令会搜索ext4,ext3和vfat文件系统。</p><pre><code>$ findmnt -t ext4,ext3,vfat
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-types.png" alt="findmnt types"></p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>你可以按照你的需要尝试不同的findmnt选项。</p><hr>`,48)),i("p",null,[n[4]||(n[4]=t("via: ",-1)),d(e,{href:"http://linoxide.com/linux-command/powerful-findmnt-command/"},{default:o(()=>[...n[3]||(n[3]=[t("http://linoxide.com/linux-command/powerful-findmnt-command/",-1)])]),_:1})]),i("p",null,[n[7]||(n[7]=t("译者：",-1)),d(e,{href:"https://github.com/zzlyzq"},{default:o(()=>[...n[5]||(n[5]=[t("zzlyzq",-1)])]),_:1}),n[8]||(n[8]=t(" 校对：",-1)),d(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[11]||(n[11]=t("本文由 ",-1)),d(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原创翻译，",-1)),d(e,{href:"http://linux.cn/"},{default:o(()=>[...n[10]||(n[10]=[t("Linux中国",-1)])]),_:1}),n[13]||(n[13]=t(" 荣誉推出",-1))])])}const F=a(s,[["render",f]]);export{y as __pageData,F as default};
